//! GraphQL schema: QueryRoot and MutationRoot are derived from the entity list
//! via `schema_roots!`. Add a new entity in the entities module and in the
//! list below; Queries/Mutations/CustomOperations are generated by the macro.

use std::sync::Arc;

use async_graphql::Schema;
use async_graphql::dataloader::DataLoader;
use macros::schema_roots;

use crate::db::Database;
use crate::services::graphql::entities::*;
use crate::services::graphql::loaders::RelationLoader;
use crate::services::graphql::mutations::{
    ArtworkMutations, AuthMutations, FilesystemMutations, LibraryScanMutations,
};
use crate::services::graphql::queries::{FilesystemQueries, SchemaMigrationsQueries};
use crate::services::graphql::subscriptions::filesystem::FilesystemChangeBroker;
use crate::services::graphql::subscriptions::{FilesystemSubscriptions, TorrentSubscriptions};
use crate::services::manager::ServicesManager;
use crate::services::metadata::providers::{MetadataServiceConfig, create_metadata_service};

schema_roots! {
    query_custom_ops: [User, Torrent, Movie, Show, Album, Audiobook],
    entities: [
        Library,
        Movie,
        Person,
        MovieCastCredit,
        Collection,
        Show,
        Episode,
        MediaFile,
        Artist,
        Album,
        Track,
        Audiobook,
        Chapter,
        Torrent,
        TorrentFile,
        RssFeed,
        RssFeedItem,
        PendingFileMatch,
        Source,
        User,
        InviteToken,
        RefreshToken,
        AppSetting,
        AppLog,
        VideoStream,
        AudioStream,
        Subtitle,
        MediaChapter,
        PlaybackSession,
        PlaybackProgress,
        CastDevice,
        CastSession,
        CastSetting,
        UsenetServer,
        UsenetDownload,
        ScheduleCache,
        ScheduleSyncState,
        NamingPattern,
        SourcePriorityRule,
        Notification,
        ArtworkCache,
        TorznabCategory,
    ],
    extra_query_types: [FilesystemQueries, SchemaMigrationsQueries, SourceCustomQueries],
    extra_mutation_types: [ArtworkMutations, AuthMutations, FilesystemMutations, LibraryScanMutations, TorrentClientMutations, MovieMetadataMutations, ShowMetadataMutations, AlbumMetadataMutations, AudiobookMetadataMutations, SourceCustomMutations, CastMutations],
    extra_subscription_types: [FilesystemSubscriptions, TorrentSubscriptions],
}

/// The GraphQL schema type
pub type LibrarianSchema = Schema<QueryRoot, MutationRoot, SubscriptionRoot>;

/// Build the GraphQL schema with all resolvers.
/// Pass the [ServicesManager] so resolvers can obtain the torrent service etc.
pub fn build_schema<E>(
    db: Database,
    auth_service: E,
    services: Arc<ServicesManager>,
) -> LibrarianSchema
where
    E: Send + Sync + Clone + 'static,
{
    // Entity change channels used by generated GraphQL subscriptions.
    let (library_changed_tx, _) = tokio::sync::broadcast::channel::<LibraryChangedEvent>(256);
    let (movie_changed_tx, _) = tokio::sync::broadcast::channel::<MovieChangedEvent>(256);
    let (show_changed_tx, _) = tokio::sync::broadcast::channel::<ShowChangedEvent>(256);
    let (episode_changed_tx, _) = tokio::sync::broadcast::channel::<EpisodeChangedEvent>(256);
    let (media_file_changed_tx, _) = tokio::sync::broadcast::channel::<MediaFileChangedEvent>(256);
    let (artist_changed_tx, _) = tokio::sync::broadcast::channel::<ArtistChangedEvent>(256);
    let (album_changed_tx, _) = tokio::sync::broadcast::channel::<AlbumChangedEvent>(256);
    let (track_changed_tx, _) = tokio::sync::broadcast::channel::<TrackChangedEvent>(256);
    let (audiobook_changed_tx, _) = tokio::sync::broadcast::channel::<AudiobookChangedEvent>(256);
    let (chapter_changed_tx, _) = tokio::sync::broadcast::channel::<ChapterChangedEvent>(256);
    let (notification_changed_tx, _) =
        tokio::sync::broadcast::channel::<NotificationChangedEvent>(256);
    let (app_log_changed_tx, _) = tokio::sync::broadcast::channel::<AppLogChangedEvent>(256);

    // Create DataLoaders for batching relation queries.
    // Each loader batches queries for a specific (entity_type, fk_column) pair.
    // When multiple parents request their children in the same GraphQL request,
    // all requests are batched into a single SQL query with IN clause.
    //
    // The loaders are keyed by parent ID and return Vec<ChildEntity>.
    // Filtering, sorting, and pagination are applied in-memory after loading.

    // Library -> children
    let shows_loader = DataLoader::new(
        RelationLoader::<Show>::new(db.clone(), "library_id"),
        tokio::spawn,
    );
    let movies_loader = DataLoader::new(
        RelationLoader::<Movie>::new(db.clone(), "library_id"),
        tokio::spawn,
    );
    let collections_loader = DataLoader::new(
        RelationLoader::<Collection>::new(db.clone(), "library_id"),
        tokio::spawn,
    );
    let artists_loader = DataLoader::new(
        RelationLoader::<Artist>::new(db.clone(), "library_id"),
        tokio::spawn,
    );
    let albums_by_library_loader = DataLoader::new(
        RelationLoader::<Album>::new(db.clone(), "library_id"),
        tokio::spawn,
    );
    let audiobooks_loader = DataLoader::new(
        RelationLoader::<Audiobook>::new(db.clone(), "library_id"),
        tokio::spawn,
    );

    // Show -> Episodes
    let episodes_loader = DataLoader::new(
        RelationLoader::<Episode>::new(db.clone(), "show_id"),
        tokio::spawn,
    );

    // Artist -> Albums
    let albums_by_artist_loader = DataLoader::new(
        RelationLoader::<Album>::new(db.clone(), "artist_id"),
        tokio::spawn,
    );

    // Album -> Tracks
    let tracks_loader = DataLoader::new(
        RelationLoader::<Track>::new(db.clone(), "album_id"),
        tokio::spawn,
    );

    // Audiobook -> Chapters
    let chapters_loader = DataLoader::new(
        RelationLoader::<Chapter>::new(db.clone(), "audiobook_id"),
        tokio::spawn,
    );

    // Torrent -> TorrentFiles
    let torrent_files_loader = DataLoader::new(
        RelationLoader::<TorrentFile>::new(db.clone(), "torrent_id"),
        tokio::spawn,
    );

    // Create MetadataService - it will load API keys from database on demand
    let metadata_service = create_metadata_service(
        db.clone(),
        services.clone(),
        MetadataServiceConfig::default(),
    );

    Schema::build(
        QueryRoot::default(),
        MutationRoot::default(),
        SubscriptionRoot::default(),
    )
    .data(db)
    .data(auth_service)
    .data(services)
    .data(metadata_service)
    .data(FilesystemChangeBroker::new(64))
    // Entity subscription channels
    .data(library_changed_tx)
    .data(movie_changed_tx)
    .data(show_changed_tx)
    .data(episode_changed_tx)
    .data(media_file_changed_tx)
    .data(artist_changed_tx)
    .data(album_changed_tx)
    .data(track_changed_tx)
    .data(audiobook_changed_tx)
    .data(chapter_changed_tx)
    .data(notification_changed_tx)
    .data(app_log_changed_tx)
    // Register all relation DataLoaders
    .data(shows_loader)
    .data(movies_loader)
    .data(collections_loader)
    .data(artists_loader)
    .data(albums_by_library_loader)
    .data(albums_by_artist_loader)
    .data(audiobooks_loader)
    .data(episodes_loader)
    .data(tracks_loader)
    .data(chapters_loader)
    .data(torrent_files_loader)
    .finish()
}
